import { execFileSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { createServer, type IncomingMessage } from 'node:http';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { audit, refactorPlan, releaseReadiness, understand } from './index.js';
import { verificationPlan } from './verify.js';
import { buildArchitecturalRefactorPlan } from './refactor-planner.js';
import { applyReorganizationMove } from './reorganization.js';
import { architectureDiff, writeReorganizationReport } from './reporters.js';
import type { ArchitecturalRefactorPlan } from './refactor-types.js';

export function openBrowser(file: string): boolean {
  const url = /^https?:\/\//.test(file) ? file : pathToFileURL(file).href;
  try {
    if (process.platform === 'win32') {
      // Windows may associate .html with Notepad. Prefer an installed browser
      // explicitly by checking where.exe, then fall back to the user's default handler.
      for (const browser of ['msedge.exe', 'chrome.exe', 'firefox.exe']) {
        try {
          execFileSync('where.exe', [browser], { stdio: 'ignore' });
          execFileSync('cmd', ['/c', 'start', '', browser, url], { stdio: 'ignore' });
          return true;
        } catch { /* try the next browser */ }
      }
      execFileSync('cmd', ['/c', 'start', '', url], { stdio: 'ignore' });
    }
    else if (process.platform === 'darwin') execFileSync('open', [url], { stdio: 'ignore' });
    else execFileSync('xdg-open', [url], { stdio: 'ignore' });
    return true;
  } catch { return false; }
}

function reorganizationPlanPath(target: string): string { return join(resolve(target), '.ycf', 'reorganization-plan.json'); }

function readReorganizationPlan(target: string): ArchitecturalRefactorPlan | undefined {
  const path = reorganizationPlanPath(target);
  if (!existsSync(path)) return undefined;
  try { return JSON.parse(readFileSync(path, 'utf8')) as ArchitecturalRefactorPlan; } catch { return undefined; }
}

// Rejects on malformed JSON in the body and on a client `req` 'error' event (e.g. the
// browser navigating away mid-POST). EVERY caller MUST wrap `await readJsonBody(req)` in
// its own try/catch and respond 400 with a JSON error body on failure, then `return` --
// an uncaught rejection here becomes an unhandled promise rejection on the Node process,
// which crashes the whole server under Node's default behavior. Do not `await` this
// directly inside a route handler without a surrounding try/catch.
function readJsonBody(req: IncomingMessage): Promise<Record<string, unknown>> {
  return new Promise((resolvePromise, rejectPromise) => {
    let data = '';
    req.on('data', (chunk) => { data += chunk; });
    req.on('end', () => { try { resolvePromise(data ? JSON.parse(data) : {}); } catch (error) { rejectPromise(error); } });
    req.on('error', rejectPromise);
  });
}

// Local re-check-and-apply server for the Cockpit. Binds to 127.0.0.1 only (never
// reachable from another machine) and requires an exact per-session token on every
// request via the x-ycf-token header. Most endpoints are read-only plan endpoints.
// The write endpoints -- /apply/move, /undo/move, /keep/move, /finalize, and
// /finalize/publish -- never invent a move: every one of them only ever executes a
// move that already exists, verbatim, in .ycf/reorganization-plan.json, written by an
// AI agent after the user approved it in chat. See
// docs/superpowers/specs/2026-08-19-ai-residue-and-cockpit-reorg-design.md.
export function startCockpitServer(target: string, port: number, onError?: (error: Error) => void): { url: string; token: string; close: () => void } {
  const token = randomBytes(16).toString('hex');
  // Per-server-instance only, by design -- see docs/superpowers/specs/2026-08-19-ai-residue-and-cockpit-reorg-design.md.
  // Undo/Keep only work while this exact process is still running; restarting Cockpit loses
  // this map, but every applied change is already sitting uncommitted in the working tree,
  // recoverable with plain git like any other YCF change.
  const appliedMoves = new Map<string, Extract<ReturnType<typeof applyReorganizationMove>, { status: 'applied' }>>();
  const keptMoves = new Set<string>();
  let baseline: { score: number; architecture: ReturnType<typeof understand>['graph'] } | undefined;
  const server = createServer(async (req, res) => {
    // The cockpit HTML is opened via file:// (or occasionally served on a different
    // port), so the browser treats every request here as cross-origin and preflights
    // it because of the custom x-ycf-token header. The per-session random token, not
    // the origin, is what gates access -- this server only ever binds to loopback.
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Headers', 'x-ycf-token');
    if (req.method === 'OPTIONS') { res.writeHead(204); res.end(); return; }
    const url = new URL(req.url ?? '/', 'http://127.0.0.1');
    // The menu and the two live run-and-show pages are opened by plain browser
    // navigation (clicking a link), so they can't carry the x-ycf-token header the
    // /plan/* API below requires -- the token travels as a query parameter instead.
    // Same threat model as the header-gated routes: loopback-only, per-session random
    // token, nothing persisted.
    if (url.pathname === '/menu' || url.pathname === '/run/audit' || url.pathname === '/run/release') {
      if (url.searchParams.get('token') !== token) { res.writeHead(403, { 'Content-Type': 'text/plain' }); res.end('Invalid or missing token.'); return; }
      if (url.pathname === '/menu') { res.writeHead(200, { 'Content-Type': 'text/html' }); res.end(menuHtml(target, token)); return; }
      if (url.pathname === '/run/audit') {
        const bootstrap = `<script>window.__YCF_COCKPIT__=${JSON.stringify({ token, base: `http://127.0.0.1:${port}` })};</script>`;
        const html = cockpitHtml(understand(target), audit(target), verificationPlan(target)).replace('</body>', `${bootstrap}${cockpitActionsHtml()}</body>`);
        res.writeHead(200, { 'Content-Type': 'text/html' }); res.end(html); return;
      }
      res.writeHead(200, { 'Content-Type': 'text/html' }); res.end(releaseReadinessHtml(releaseReadiness(target), token)); return;
    }
    if (req.headers['x-ycf-token'] !== token) { res.writeHead(403, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'invalid token' })); return; }
    if (url.pathname === '/plan/audit') { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(audit(target))); return; }
    if (url.pathname === '/plan/refactor') { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(refactorPlan(target))); return; }
    if (url.pathname === '/plan/architectural') { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(buildArchitecturalRefactorPlan(target))); return; }
    if (url.pathname === '/plan/reorganization') {
      const plan = readReorganizationPlan(target);
      if (!plan) { res.writeHead(404, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'no reorganization plan yet' })); return; }
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ plan, applied: [...appliedMoves.keys()], kept: [...keptMoves] }));
      return;
    }
    if (req.method === 'POST' && url.pathname === '/apply/move') {
      let body: Record<string, unknown>;
      try { body = await readJsonBody(req); }
      catch { res.writeHead(400, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'invalid request body' })); return; }
      const blockId = String(body.blockId ?? '');
      const plan = readReorganizationPlan(target);
      const block = plan?.blocks.find((candidate) => candidate.id === blockId);
      if (!block) { res.writeHead(404, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'unknown blockId' })); return; }
      if (appliedMoves.has(blockId)) { res.writeHead(409, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'already applied this session' })); return; }
      if (block.operations.length !== 1 || !(block.operations[0].kind === 'MOVE' || block.operations[0].kind === 'RENAME')) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'block must contain exactly one MOVE or RENAME operation' }));
        return;
      }
      if (!baseline) {
        try { baseline = { score: audit(target).score.fucked, architecture: understand(target).graph }; }
        catch (error) { res.writeHead(500, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: error instanceof Error ? error.message : String(error) })); return; }
      }
      const result = applyReorganizationMove(target, block);
      if (result.status === 'rolled_back') { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ status: 'rolled_back', error: result.error })); return; }
      appliedMoves.set(blockId, result);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'applied', changedFiles: result.changedFiles }));
      return;
    }
    if (req.method === 'POST' && url.pathname === '/undo/move') {
      let body: Record<string, unknown>;
      try { body = await readJsonBody(req); }
      catch { res.writeHead(400, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'invalid request body' })); return; }
      const blockId = String(body.blockId ?? '');
      const applied = appliedMoves.get(blockId);
      if (!applied || keptMoves.has(blockId)) { res.writeHead(404, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'no undoable applied move with that blockId in this session' })); return; }
      try { for (const operation of [...applied.applied].reverse()) operation.undo(); }
      catch (error) { res.writeHead(500, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: error instanceof Error ? error.message : String(error) })); return; }
      appliedMoves.delete(blockId);
      res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ status: 'pending' })); return;
    }
    if (req.method === 'POST' && url.pathname === '/keep/move') {
      let body: Record<string, unknown>;
      try { body = await readJsonBody(req); }
      catch { res.writeHead(400, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'invalid request body' })); return; }
      const blockId = String(body.blockId ?? '');
      if (!appliedMoves.has(blockId)) { res.writeHead(404, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'no applied move with that blockId in this session' })); return; }
      keptMoves.add(blockId);
      res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ status: 'kept' })); return;
    }
    if (req.method === 'POST' && url.pathname === '/finalize') {
      try { await readJsonBody(req); }
      catch { res.writeHead(400, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'invalid request body' })); return; }
      try {
        const afterArchitecture = understand(target).graph;
        const afterScore = audit(target).score.fucked;
        const diff = architectureDiff(baseline?.architecture ?? afterArchitecture, afterArchitecture);
        const summary = { appliedBlockIds: [...appliedMoves.keys()], keptBlockIds: [...keptMoves], beforeScore: baseline?.score ?? afterScore, afterScore, architecture: diff };
        const paths = writeReorganizationReport(target, summary);
        res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ ...summary, reportPath: paths.markdownPath })); return;
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: error instanceof Error ? error.message : String(error) })); return;
      }
    }
    if (req.method === 'POST' && url.pathname === '/finalize/publish') {
      let body: Record<string, unknown>;
      try { body = await readJsonBody(req); }
      catch { res.writeHead(400, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'invalid request body' })); return; }
      const push = body.push === true;
      const changedFiles = [...new Set([...appliedMoves.values()].flatMap((entry) => entry.changedFiles))];
      if (!changedFiles.length) { res.writeHead(400, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'nothing applied this session to commit' })); return; }
      try {
        for (const file of changedFiles) execFileSync('git', ['-C', target, 'add', '--', file], { stdio: 'ignore' });
        execFileSync('git', ['-C', target, 'commit', '-m', 'YCF: apply approved reorganization plan'], { stdio: 'ignore' });
      } catch (error) { res.writeHead(500, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: `commit failed: ${error instanceof Error ? error.message : String(error)}` })); return; }
      if (!push) { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ status: 'committed' })); return; }
      try {
        execFileSync('git', ['-C', target, 'push'], { stdio: 'ignore' });
        res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ status: 'pushed' }));
      } catch (error) {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'committed', pushError: `Committed locally, but push failed (no remote/upstream configured, or authentication is required): ${error instanceof Error ? error.message : String(error)}` }));
      }
      return;
    }
    res.writeHead(404, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'not found' }));
  });
  server.on('error', onError ?? (() => {}));
  server.listen(port, '127.0.0.1');
  return { url: `http://127.0.0.1:${port}`, token, close: () => server.close() };
}

