export function menuHtml(target: string, token: string): string {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YCF — Fuck-O-Meter</title><style>body{margin:0;background:#080d18;color:#e5e7eb;font:16px system-ui,sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh}main{max-width:520px;padding:32px;text-align:center}h1{color:#fb7185;margin:0 0 8px}p{color:#94a3b8;margin:0 0 20px;word-break:break-all}.langtabs{display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:20px}.langtabs button{background:#1e293b;color:#94a3b8;border:1px solid #334155;border-radius:6px;padding:4px 10px;font-size:12px;cursor:pointer}.langtabs button.active{background:#9f1239;color:#fff;border-color:#fb7185}.buttons{display:flex;flex-direction:column;gap:12px}a{display:block;background:#1e293b;color:#e5e7eb;border:1px solid #475569;border-radius:10px;padding:16px;text-decoration:none;font-size:17px}a:hover{background:#9f1239;border-color:#fb7185}small{color:#64748b;display:block;margin-top:24px}</style></head><body><main><div class="langtabs" id="langtabs"></div><h1>YCF — Fuck-O-Meter</h1><p>${target.replace(/\\/g, '/')}</p><div class="buttons"><a href="/run/audit?token=${token}" data-i18n="analyze">🔍 Analyze my project</a><a href="/run/release?token=${token}" data-i18n="release">🚀 Is this ready to ship?</a></div><small data-i18n="footer">Read-only. Nothing here changes your code.</small></main><script>const I18N=${JSON.stringify(MENU_I18N)};const bar=document.querySelector('#langtabs');Object.keys(I18N).forEach(code=>{const b=document.createElement('button');b.textContent=code.toUpperCase();b.dataset.lang=code;if(code==='en')b.className='active';b.onclick=()=>setLang(code);bar.appendChild(b)});function setLang(code){document.querySelectorAll('#langtabs button').forEach(b=>b.classList.toggle('active',b.dataset.lang===code));document.documentElement.dir=code==='ar'?'rtl':'ltr';document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(I18N[code][key])el.textContent=I18N[code][key]})}</script></body></html>`;
}

export function releaseReadinessHtml(report: ReturnType<typeof releaseReadiness>, token: string): string {
  const checks = report.checks.map((check) => `<li class="${check.status}"><b>${check.name}</b> — ${check.status}<br><span>${check.detail}</span></li>`).join('');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YCF — release readiness</title><style>body{margin:0;background:#080d18;color:#e5e7eb;font:15px system-ui,sans-serif;padding:30px}h1{color:#fb7185}ul{list-style:none;padding:0;margin:0 0 20px}li{background:#111827;border:1px solid #26324a;border-radius:10px;padding:14px;margin-bottom:10px}li.failed{border-color:#f87171}li.warning{border-color:#facc15}li.passed{border-color:#4ade80}span{color:#94a3b8}a{color:#fda4af}</style></head><body><h1>YCF — ${report.ready ? 'READY' : 'REVIEW REQUIRED'}</h1><ul>${checks}</ul><p><a href="/menu?token=${token}">&larr; Back</a></p></body></html>`;
}

export function cockpitActionsHtml(): string {
  return `<section class="actions"><h2>What do you want YCF to do?</h2><p class="hint">YCF never runs anything from this page by itself. Pick an action, and it gives you the exact command to run in your terminal.</p><div class="action-buttons"><button data-ycf-action="🔍 Analyze my project" data-ycf-command="ycf audit ." data-ycf-plan="audit">🔍 Analyze my project</button><button data-ycf-action="🗺 Understand my code" data-ycf-command="ycf explain .">🗺 Understand my code</button><button data-ycf-action="🧹 Unfuck safe stuff" data-ycf-command="ycf cleanup . --dry-run">🧹 Unfuck safe stuff</button><button data-ycf-action="🔧 Organize &amp; refactor" data-ycf-command="ycf refactor . --dry-run" data-ycf-plan="refactor">🔧 Organize &amp; refactor</button><button data-ycf-action="🚀 Is this ready to ship?" data-ycf-command="ycf release .">🚀 Is this ready to ship?</button></div><div id="ycf-action-result" class="action-result" style="display:none"><p id="ycf-action-label"></p><code id="ycf-action-command"></code><p id="ycf-action-status" class="hint"></p></div><script>document.querySelectorAll('[data-ycf-action]').forEach((button)=>button.onclick=async ()=>{const command=button.dataset.ycfCommand;const box=document.querySelector('#ycf-action-result');box.style.display='block';document.querySelector('#ycf-action-label').textContent=button.dataset.ycfAction+' — run this in your terminal, inside your project folder:';const commandEl=document.querySelector('#ycf-action-command');commandEl.textContent=command;const status=document.querySelector('#ycf-action-status');const cockpit=window.__YCF_COCKPIT__;if(cockpit && button.dataset.ycfPlan){try{const response=await fetch(cockpit.base+'/plan/'+button.dataset.ycfPlan,{headers:{'x-ycf-token':cockpit.token}});const plan=await response.json();status.textContent='Live read-only re-check ran — see the plan below. To apply anything, run the command above in your terminal (YCF never applies changes from this page).';const pre=document.createElement('pre');pre.style.cssText='max-height:240px;overflow:auto;background:#0f172a;padding:10px;border-radius:8px;margin-top:8px';pre.textContent=JSON.stringify(plan,null,2);box.appendChild(pre);return;}catch(error){/* server not running (e.g. --no-server) — fall through to copy-only */}}navigator.clipboard?.writeText(command).then(()=>{status.textContent='Copied to your clipboard — just paste it in your terminal.';}).catch(()=>{const range=document.createRange();range.selectNodeContents(commandEl);const selection=window.getSelection();if(selection){selection.removeAllRanges();selection.addRange(range);}status.textContent="Couldn't copy automatically — it's selected above, press Ctrl+C / Cmd+C.";});});</script></section>`;
}
